// Webhook Relay signature check (generated by the Jenkins plugin).
// Rejects the request at the relay unless it carries a valid X-Hub-Signature-256, so
// unsigned or forged requests never reach Jenkins.
const secret = cfg.get("WEBHOOK_SECRET") || ""
const received = r.headers["X-Hub-Signature-256"] || ""
const expected = "sha256=" + crypto.hmac("sha256", secret, r.body)
// Compare HMACs of both values so response time does not reveal how much
// of a guessed signature matched.
if (!secret || !received ||
    crypto.hmac("sha256", secret, received) !== crypto.hmac("sha256", secret, expected)) {
  r.setResponseStatus(401)
  r.setResponseBody("invalid webhook signature")
  r.stopForwarding()
}
